// ❌ OLD: Combining fast-changing and slow-changing state into one context object.
// Toggling the theme re-renders the UserAvatar component even though user hasn't changed!
import { createContext, useContext, useState } from 'react';

const AppContext = createContext(null);

export function AppProvider({ children }) {
  const [user, setUser] = useState({ name: 'Ada' });
  const [theme, setTheme] = useState('dark');

  // New object reference created on every state change:
  return (
    <AppContext.Provider value={{ user, setUser, theme, setTheme }}>
      {children}
    </AppContext.Provider>
  );
}

export function UserAvatar() {
  const { user } = useContext(AppContext); // ❌ Re-renders when theme toggles!
  return <div>{user.name}</div>;
}

// ✅ NEW: Split contexts by domain and update frequency.
import { createContext, useContext, useState } from 'react';

const UserContext = createContext(null);
const ThemeContext = createContext(null);

export function AppProvider({ children }) {
  const [user] = useState({ name: 'Ada' });
  const [theme, setTheme] = useState('dark');

  return (
    <ThemeContext.Provider value={{ theme, setTheme }}>
      <UserContext.Provider value={user}>
        {children}
      </UserContext.Provider>
    </ThemeContext.Provider>
  );
}

export function UserAvatar() {
  const user = useContext(UserContext); // ✅ Only re-renders if user changes!
  return <div>{user.name}</div>;
}
